:root {
  --cream: #f5eedf;
  --parchment: #e8d9bc;
  --border-brown: #8b6a3e;
  --dark-brown: #3e2510;
  --mid-brown: #6b4423;
  --gold: #c8963e;
  --gold-light: #e8b96a;
  --top-note: #d4e8d0;
  --top-note-border: #6a9e62;
  --heart-note: #f0dce8;
  --heart-note-border: #b06090;
  --base-note: #ddd0e8;
  --base-note-border: #7a5a9e;
  --dot-filled: #8b6a3e;
  --dot-empty: #d4c4a8;
  --badge-bg: #3e2510;
  --badge-text: #e8d9bc;
}

article.blend-card {
  background-color: var(--cream);
  border: 2px solid var(--border-brown);
  border-radius: 4px;
  width: 460px;
  padding: 0;
  outline: 1px solid var(--gold);
  outline-offset: -5px;
}

.card-header {
  background-color: var(--dark-brown);
  padding: 10px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 2px solid var(--gold);
}

.atelier-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 3px;
  color: var(--gold-light);
  text-transform: uppercase;
}

.atelier-name {
  font-size: 18px;
  font-weight: 700;
  color: var(--cream);
  margin: 0;
  letter-spacing: 1px;
}

.card-number {
  font-size: 11px;
  color: var(--parchment);
  font-style: italic;
}

.formula-section {
  padding: 12px 16px 8px;
  border-bottom: 1px dashed var(--border-brown);
}

.section-title {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--mid-brown);
  margin: 0 0 8px 0;
}

.notes-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.note-row {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 5px 8px;
  border-radius: 3px;
  border-left: 3px solid transparent;
}

.note-row.top {
  background-color: var(--top-note);
  border-left-color: var(--top-note-border);
}

.note-row.heart {
  background-color: var(--heart-note);
  border-left-color: var(--heart-note-border);
}

.note-row.base {
  background-color: var(--base-note);
  border-left-color: var(--base-note-border);
}

.note-tier {
  font-size: 10px;
  font-weight: 700;
  color: var(--dark-brown);
  width: 100px;
  flex-shrink: 0;
}

.note-name {
  font-size: 12px;
  color: var(--mid-brown);
  flex: 1;
  font-style: italic;
}

.note-pct {
  font-size: 12px;
  font-weight: 700;
  color: var(--border-brown);
  width: 32px;
  text-align: right;
}

.meta-section {
  display: flex;
  align-items: center;
  gap: 0;
  padding: 10px 16px;
  border-bottom: 1px dashed var(--border-brown);
}

.sillage-block,
.accord-block,
.yield-block {
  flex: 1;
  margin: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 5px;
}

.sillage-block {
  border-right: 1px solid var(--parchment);
}

.accord-block {
  border-right: 1px solid var(--parchment);
}

.meta-label {
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--mid-brown);
}

.sillage-dots {
  display: flex;
  gap: 4px;
  align-items: center;
}

.dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  border: 1px solid var(--border-brown);
  display: inline-block;
}

.dot.filled {
  background-color: var(--dot-filled);
}

.dot.half {
  background: linear-gradient(90deg, var(--dot-filled) 50%, var(--dot-empty) 50%);
}

.dot.empty {
  background-color: var(--dot-empty);
}

.accord-badge {
  background-color: var(--badge-bg);
  color: var(--badge-text);
  font-size: 11px;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 12px;
  letter-spacing: 0.5px;
}

.yield-value {
  font-size: 20px;
  font-weight: 700;
  color: var(--dark-brown);
  line-height: 1;
}

.card-footer {
  background-color: var(--parchment);
  padding: 8px 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 2px solid var(--border-brown);
}

.footer-date {
  font-size: 10px;
  color: var(--mid-brown);
  font-style: italic;
}

.footer-parfumeur {
  font-size: 10px;
  color: var(--dark-brown);
  font-weight: 700;
}

.footer-seal {
  font-size: 10px;
  color: var(--gold);
  letter-spacing: 2px;
  font-weight: 700;
}
